package com.example.ecommerce.servlet;
import com.example.ecommerce.dao.UserDAO; import com.example.ecommerce.model.User; import javax.servlet.*; import javax.servlet.annotation.*; import javax.servlet.http.*; import java.io.IOException;
@WebServlet("/register") public class RegisterServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/register.jsp").forward(r,p);}protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{UserDAO dao=new UserDAO();String email=req.getParameter("email");if(dao.emailExists(email)){req.setAttribute("error","Bu e-posta daha önce kayıtlı.");doGet(req,resp);return;}User u=new User();u.setFullName(req.getParameter("fullName"));u.setEmail(email);u.setPassword(req.getParameter("password"));u.setPhone(req.getParameter("phone"));u.setAddress(req.getParameter("address"));dao.register(u);resp.sendRedirect(req.getContextPath()+"/login?registered=1");}catch(Exception e){throw new ServletException(e);}}}
